import{_ as s,C as i,o as n,c as l,a9 as r,E as o,j as t}from"./chunks/framework.BOiBTRPC.js";const y=JSON.parse('{"title":"Databricks Practice Drill","description":"Original practice sets aligned to the Databricks Certified Data Engineer Associate blueprint — Delta Lake, ingestion, streaming, governance, Lakeflow pipelines, and workflows — as a spaced-repetition drill that cross-links the real chapters.","frontmatter":{"title":"Databricks Practice Drill","description":"Original practice sets aligned to the Databricks Certified Data Engineer Associate blueprint — Delta Lake, ingestion, streaming, governance, Lakeflow pipelines, and workflows — as a spaced-repetition drill that cross-links the real chapters."},"headers":[],"relativePath":"interview/databricks-practice.md","filePath":"interview/databricks-practice.md"}'),d={name:"interview/databricks-practice.md"};function c(h,e,p,u,m,g){const a=i("QuizCard");return n(),l("div",null,[e[0]||(e[0]=r("",9)),o(a,{questions:[{q:"Analysts and engineers keep publishing conflicting numbers from siloed copies of the same data. Which property of a lakehouse fixes this at the architecture level?",options:["Real-time co-editing in shared notebooks","Autoscaling compute for both teams","One open storage layer serving as the single source of truth for every workload","A scheduled sync job that keeps two warehouses identical"],correct:2,explain:"The lakehouse puts one governed copy of the data on open storage that BI and engineering both read. Shared notebooks and syncing copies are workarounds; the fix is eliminating the copies."},{q:"Two jobs run against the same Delta table and one does not leave the table half-written or corrupted. What provides that guarantee?",options:["ACID transactions over the Delta transaction log","Unity Catalog row-level permissions","The metastore locking the table for readers","Photon vectorized execution"],correct:0,explain:"Delta Lake records every commit in _delta_log and resolves concurrent writers with optimistic concurrency — readers always see a consistent snapshot. Permissions govern who can read; ACID governs what a write looks like mid-flight."},{q:"Which description of a Delta table on storage is accurate?",options:["One self-contained file holding data plus history","Data in one file, all metadata in a separate collection of files","A collection of files holding data, with metadata and version history alongside them","A collection of data files only, since the metastore owns all metadata"],correct:2,explain:"A Delta table is a directory of Parquet data files plus the _delta_log transaction log — the log carries metadata, commit history, and per-file stats, which is what makes time travel possible."},{q:"An engineer needs to remove every row where age is greater than 25 from an existing Delta table. Which statement does it?",options:["SELECT * FROM my_table WHERE age <= 25","UPDATE my_table WHERE age > 25","DELETE FROM my_table WHERE age <= 25","DELETE FROM my_table WHERE age > 25"],correct:3,explain:"DELETE FROM removes the rows matching the predicate — here age > 25. UPDATE rewrites column values, and the flipped predicate would delete exactly the rows you wanted to keep."},{q:"Time travel to a three-day-old version fails because the underlying data files are gone. What most likely deleted them?",options:["OPTIMIZE compacted the table","VACUUM ran with a retention window shorter than three days","A scheduled RESTORE checkpoint","The HISTORY command trimmed the log"],correct:1,explain:"VACUUM permanently deletes data files no longer referenced by versions inside the retention window — once it runs, versions older than that window are unrecoverable. OPTIMIZE only rewrites live files."}]}),e[1]||(e[1]=t("p",null,[t("strong",null,"Set 2 — Platform, governance & compute")],-1)),o(a,{questions:[{q:"In the classic Databricks architecture, which component lives entirely in the control plane?",options:["The cluster driver node","The Databricks web application","The Databricks Filesystem (DBFS)","The JDBC-connected source database"],correct:1,explain:"The control plane hosts the web app, REST API, and workspace services; the data plane — drivers, workers, your storage — runs in your cloud account. Anything that executes or stores your data is data plane."},{q:"A nightly job must start producing a report within seconds of its trigger, and cold cluster-start latency is the bottleneck. What helps most?",options:["Switching to a SQL warehouse","Attaching the job to a cluster pool","Enabling Photon on the cluster","Increasing the worker count"],correct:1,explain:"Pools keep idle instances warm so a cluster can grab them in seconds instead of waiting for cloud provisioning. Photon speeds execution; it does nothing for start latency."},{q:"An engineer leaves the company and their Delta tables need a new owner, but the departing engineer no longer has access. Who can transfer ownership?",options:["The replacement lead engineer","The Databricks account representative","A workspace administrator","Any member of the same group"],correct:2,explain:"Object ownership can be reassigned by a workspace (or metastore) admin — ownership is an admin-managed grant, so it never depends on the departed user still having access."},{q:"Which advantage do Databricks Repos give you over a notebook's built-in version history?",options:["Automatic saving of progress","Reverting a notebook to a previous version","Commenting inline on specific changes","Git branching for parallel feature work"],correct:3,explain:"Notebook history is a linear undo trail; Repos plug into real Git, so branching, pull requests, and multi-branch collaboration exist — things version history simply does not model."},{q:"Which Git operation can NOT be performed inside Databricks Repos?",options:["Merge","Commit","Pull","Clone"],correct:0,explain:"Repos covers commit/pull/push/clone and branch switching, but merging branches (and resolving conflicts) happens in your Git provider — by design, so reviews live in PRs."}]}),e[2]||(e[2]=t("p",null,[t("strong",null,"Set 3 — Ingestion & SQL/Spark on the platform")],-1)),o(a,{questions:[{q:"A shared landing directory accumulates files from several processes that cannot be moved or deleted. The pipeline must pick up only new files each run. Which tool fits?",options:["COPY INTO with a FILES list","Auto Loader","A JDBC read against the file store","Delta Live Tables expectations"],correct:1,explain:"Auto Loader tracks which files it has already processed via checkpointed state, so it ingests only new arrivals — exactly the incremental-file-discovery problem. COPY INTO also dedupes but expects you to scope the source."},{q:"A daily COPY INTO job runs against yesterday's file in /transactions/raw, but the row count in the target table does not change. Most likely cause?",options:["Parquet is unsupported by COPY INTO","The file needs FORMAT_OPTIONS declared","That file was already loaded in a previous run","The table requires a REFRESH to see copied rows"],correct:2,explain:"COPY INTO records which files it has loaded and skips them on re-runs — it is idempotent by design. A no-change run almost always means this input was already ingested."},{q:"An engineer must build a Delta table from an existing SQLite database. Which clause completes CREATE TABLE ... USING ___?",options:["sqlite","autoloader","org.apache.spark.sql.jdbc","DELTA"],correct:2,explain:"Spark reads relational databases through the JDBC data source, fully qualified as org.apache.spark.sql.jdbc — SQLite is reached the same way. USING DELTA describes the target format, not the source."},{q:"The engineering team writes tests in Python but needs to read the analyst-created table sales. Which PySpark call accesses it?",options:['spark.sql("sales")',"SELECT * FROM sales",'spark.delta.table("sales")','spark.table("sales")'],correct:3,explain:'spark.table("sales") loads a metastore-registered table as a DataFrame — the SQL/PySpark boundary is just the catalog, no export step needed. spark.sql("sales") fails because the string is not a query.'},{q:"Two monthly tables, march_transactions and april_transactions, have no overlapping rows. Which builds one deduplicated all_transactions table?",options:["UNION","INNER JOIN","INTERSECT","OUTER JOIN"],correct:0,explain:"UNION stacks both row sets and removes duplicates; UNION ALL keeps them. Joins combine columns by key, INTERSECT returns only shared rows — none of those concatenate."},{q:"A nightly job must upsert records into a Delta table without writing duplicates. Which command is built for that?",options:["APPEND","INSERT","IGNORE","MERGE"],correct:3,explain:"MERGE INTO is the upsert: matched rows update, unmatched rows insert, keyed on a join condition. INSERT and APPEND always add rows — duplicates included."}]}),e[3]||(e[3]=t("p",null,[t("strong",null,"Set 4 — Structured Streaming & medallion")],-1)),o(a,{questions:[{q:"Structured Streaming must record the exact offsets processed per trigger so a failed query can restart and reprocess correctly. Which two mechanisms does it use?",options:["Replayable sources and idempotent sinks","Checkpointing and write-ahead logs","VACUUM and the transaction log","Checkpointing and Unity Catalog auditing"],correct:1,explain:"Offsets go into a write-ahead log and query state into checkpoints on durable storage — together they let the engine replay from the last committed offset. Replayable sources and idempotent sinks are how you achieve exactly-once end to end, a different question."},{q:"What actually powers Auto Loader's incremental file processing?",options:["Spark Structured Streaming","Delta Live Tables","The COPY INTO command","Unity Catalog"],correct:0,explain:"Auto Loader is a Structured Streaming source (cloudFiles) — file discovery, dedup, and progress tracking all ride on streaming checkpoint infrastructure."},{q:"A streaming write should run a micro-batch every 5 seconds. Which trigger option does that?",options:['trigger("5 seconds")','trigger(once="5 seconds")','trigger(continuous="5 seconds")','trigger(processingTime="5 seconds")'],correct:3,explain:"processingTime schedules micro-batches on an interval; once runs a single batch, continuous is the low-latency experimental mode — and a bare positional argument is not valid syntax."},{q:"Which statement best describes Bronze tables relative to the raw files?",options:["They hold less data than the raw files","They are aggregated views of the raw files","They hold the raw data with a schema applied","They are a less refined view than the raw files"],correct:2,explain:"Bronze lands the raw payload but typed and structured — schema on write. Aggregation and cleaning are Silver and Gold concerns."},{q:"How do Gold tables differ from Silver tables?",options:["They hold more raw rows","They are less refined than Silver","They are more likely to hold aggregations","They contain more truthful data"],correct:2,explain:"Gold is consumption-ready data — dimensional models and precomputed aggregates. Not more truthful, just more product-shaped."}]}),e[4]||(e[4]=t("p",null,[t("strong",null,"Set 5 — Lakeflow / DLT & data quality")],-1)),o(a,{questions:[{q:"A team wants pipeline-level data quality monitoring that can drop or flag bad records automatically as data lands. Which tool?",options:["Delta Live Tables","Unity Catalog","Auto Loader","Delta Lake"],correct:0,explain:"DLT expectations (@dlt.expect / EXPECT ... ON VIOLATION) embed quality rules in the pipeline and enforce them per record. Unity Catalog governs access, Auto Loader governs discovery — neither judges row quality."},{q:'A pipeline declares CONSTRAINT valid_ts EXPECT (ts > "2020-01-01") ON VIOLATION DROP ROW. What happens to violating records?',options:["They land in the target flagged as invalid","They fail the pipeline run","They are dropped and the violation is recorded in the event log","They are routed to an automatic quarantine table"],correct:2,explain:"DROP ROW removes bad records from the target and logs the violation in the pipeline event log for auditing — it does not stop the run, and quarantine tables are something you build yourself."},{q:"Some records are being dropped somewhere in a three-table DLT pipeline. How does the engineer find which table is dropping them?",options:["Open the pipeline graph and inspect each table's data quality statistics","Enable email notifications for dropped records","It cannot be determined from the platform","Click the Error button on the pipeline page"],correct:0,explain:"Each node in the pipeline UI reports expectation metrics — rows written, dropped, failed — so clicking through the graph pinpoints the offending constraint. The Error button surfaces failures, not drops."},{q:"When should you use CREATE STREAMING LIVE TABLE instead of CREATE LIVE TABLE?",options:["When the pipeline needs complex aggregations","When the upstream dataset is a static table","Never — it is redundant syntax","When the source must be read incrementally"],correct:3,explain:"STREAMING LIVE TABLE reads its source incrementally (new records only); LIVE TABLE reads it as a batch snapshot each update. Pick by how the source grows, not by what the downstream step does."},{q:"A DLT pipeline in production runs in Continuous mode. After Start is clicked with valid definitions and pending data, what happens?",options:["All datasets update once, then the pipeline shuts down and compute terminates","Datasets refresh repeatedly until the pipeline is stopped; compute persists while it runs","Datasets update once; compute stays provisioned for testing","Only streaming datasets update, on a fixed hourly interval"],correct:1,explain:"Continuous mode keeps the pipeline live and processing until you stop it, at which point its compute is torn down — versus Triggered mode, which does one update and releases resources."},{q:"Which streaming query shape represents a Silver-to-Gold hop?",options:["A pass-through copy of the Silver schema","An aggregation over Silver records grouped by a business key","A filter that drops malformed rows","A join that appends raw source columns"],correct:1,explain:"Gold is consumption-ready data — aggregations and rollups. Dropping bad rows is Bronze-to-Silver work; a pass-through adds no refinement."}]}),e[5]||(e[5]=t("p",null,[t("strong",null,"Set 6 — Workflows, SQL & day-to-day operations")],-1)),o(a,{questions:[{q:"A morning job has one task. A new notebook must run before it to fix upstream data. What is the cleanest setup?",options:["Clone the job and edit the clone's task","Create a second job that runs the notebook earlier","Add a task to the existing job and make the original task depend on it","Merge both notebooks into one"],correct:2,explain:"Jobs are task DAGs: add the new task, then set the original task's Depends on to it. A second job gives you no ordering guarantee between them."},{q:"A manager wants a Databricks SQL query refreshed every minute for one week after launch — and zero cost after that. What enforces the stop?",options:["A DBU cap on the SQL warehouse","An end date on the query refresh schedule","A limit on who can edit the schedule","Nothing — schedules run forever"],correct:1,explain:"The query scheduler accepts a stop date, after which the refresh simply stops firing. A DBU cap throttles spend but does not guarantee the schedule ends on time."},{q:"Many analysts run small queries concurrently on one always-on SQL warehouse and latency is climbing. Which change helps?",options:["Raise the maximum of the warehouse's scaling range","Enable Auto Stop","Increase the fixed cluster size","Switch the spot instance policy to Reliability Optimized"],correct:0,explain:"Concurrency pressure needs more parallel compute — multi-cluster warehouses scale out to the max bound under load. Auto Stop saves idle cost; it never adds capacity."},{q:"An analyst's SQL script must run daily, but its final query only on Sundays. What is the practical approach?",options:["Restrict the source table's grants to Sundays","Run the whole script only on Sundays","File a feature request with Databricks","Wrap the queries in PySpark and gate the last one with Python control flow"],correct:3,explain:"SQL itself has no day-of-week branching; moving the script into PySpark gives you real control flow — check the weekday, conditionally run the final query. Everything else either blocks the daily work or never ships."},{q:"A DROP TABLE removes my_table from SHOW TABLES, but the data files are still sitting in storage. Why?",options:["The table was external","The table was managed","The table exceeded 10 GB","The table had no location set"],correct:0,explain:"For external tables, DROP TABLE deletes only the metastore entry — the files at the external location are yours to remove. Managed tables lose metadata and data together."},{q:"A SQL UDF is needed to apply custom logic to stores.city at scale. Which statement creates one?",options:["CREATE FUNCTION clean_city(city STRING) RETURN CASE ...","CREATE UDF clean_city(city STRING) RETURN CASE ...","CREATE FUNCTION clean_city(city STRING) RETURNS STRING RETURN CASE ...","CREATE FUNCTION clean_city AS CASE WHEN ..."],correct:2,explain:"SQL UDFs are made with CREATE FUNCTION ... RETURNS <type> RETURN <expression> — there is no CREATE UDF statement, and the return type must be declared."}]}),e[6]||(e[6]=r("",4))])}const b=s(d,[["render",c]]);export{y as __pageData,b as default};
